var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Test that a non-empty string is parsed correctly
    assert.strictEqual(ms('100ms'), 100);
    // Test that a non-string value (like an object) is rejected
    assert.throws(() => ms({}), Error, /val is not a non-empty string or a valid number/);
    // Test that a non-empty string with invalid syntax is handled correctly
    assert.strictEqual(ms('invalid'), undefined);
    // The broken condition allows non-strings to pass through as long as they have length > 0, e.g., arrays
    assert.strictEqual(ms([1,2,3]), undefined); // This should throw but won't due to the bug
  });
});

