var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original code limited input length to 100 characters.
    // The change replaces this with `if (false)`, which removes the check.
    // This means arbitrarily long strings are now accepted, which could be
    // a security issue or cause performance problems.
    const veryLongString = '1 year'.repeat(1000);
    assert.strictEqual(ms(veryLongString), 31557600000); // Should be valid

    // But now even longer strings that might be malformed or dangerous
    // are accepted, which the original code rejected.
    const extremelyLongString = '1 day'.repeat(10000);
    assert.strictEqual(ms(extremelyLongString), 86400000); // Should work, but the original would have rejected it
  });
});

